/*
 * A232646  Sequence (or tree or triangle) generated by these rules: 1 is in
 *          S, and if x is in S, then 2*x and 5*x are in S, and duplicates are
 *          deleted as they occur.
 * https://oeis.org/A232646
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, tabl
 * Formula:   a(n) = 2^(r-1-k) * 5^k, where r is the smallest integer with
 *            r(r+1)/2 ≥ n, and k = n - r(r-1)/2 - 1. This corresponds to the
 *            row r of the triangle <i,j> = 2^i · 5^j
 * Range:     u8 n <= 14, u16 n <= 35, u32 n <= 119, u64 n <= 434,
 *            u128 n <= 1651, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    if (n < 1) return (seq_t)0;   /* Undefined for n < 1 */

    /* Find r such that r(r+1)/2 ≥ n */
    idx_t r   = 1;
    idx_t cum = 1;
    while (n > cum) {
        r++;
        cum += r;
    }

    /* k is the offset in the row r (0‑based) */
    idx_t cum_before = cum - r;          /* r(r-1)/2 */
    idx_t k           = n - cum_before - 1;

    /* Exponents for 2 and 5 */
    idx_t e5 = k;
    idx_t e2 = r - 1 - k;

    seq_t value = (seq_t)1;

    for (idx_t i = 0; i < e2; ++i) {
        value *= (seq_t)2;
    }
    for (idx_t i = 0; i < e5; ++i) {
        value *= (seq_t)5;
    }

    return value;
}
